'use strict';
const sampleSources={blackwork:'assets/blackwork-master.png'};
// A single RAF queue owns simulator rendering. All image processing is outside pointer events.
let canvas=$('#preview'),painter=null,body=null,tattoo=null,rawUpload=null,rawPixels=null,generation=0;
let simPending=false,drag=null,processTimer=0,processingPending=false,regionRequest=0,regionLoading=false,regionReveal=false;
const state={x:468,y:354,size:100,rotation:0,opacity:78};
const simControls=Object.fromEntries(['region','size','rotation','opacity','threshold','upload','upload-status'].map(id=>[id,$('#'+id)]));
function createPainter(){try{painter=new NoirInk.SurfacePainter(canvas,makeCanvas)}catch(error){const replacement=canvas.cloneNode(true);canvas.replaceWith(replacement);canvas=replacement;painter=new NoirInk.MeshPainter(canvas,makeCanvas)} }
function draw(){simPending=false;if(regionLoading)return;painter.draw(state);if(regionReveal){regionReveal=false;canvas.style.visibility='visible';canvas.setAttribute('aria-busy','false');$('.canvas-tag').textContent='NØIR / ESTUDO DE COMPOSIÇÃO'}}
function requestDraw(){if(!simPending){simPending=true;requestAnimationFrame(draw)}}
function resetPosition(){const r=NoirInk.REGIONS[simControls.region.selectedIndex];state.x=r.home[0];state.y=r.home[1]}
function constrainCenter(){const r=NoirInk.REGIONS[simControls.region.selectedIndex];state.y=clamp(state.y,...r.zone);const s=NoirInk.profile(r,state.y),bounds=NoirInk.usableBounds(r,state.y);state.x=simControls.region.selectedIndex===0?clamp(state.x,Math.max(bounds.left,s.c-s.r*.985),Math.min(bounds.right,s.c+s.r*.985)):clamp(state.x,bounds.left,bounds.right)}
function commitInk(ink){tattoo=ink;painter.setInk(ink);requestDraw()}
function trimInk(source){const c=source.getContext('2d',{willReadFrequently:true}),data=c.getImageData(0,0,source.width,source.height).data;let minX=source.width,minY=source.height,maxX=-1,maxY=-1;for(let y=0;y<source.height;y++)for(let x=0;x<source.width;x++){if(data[(y*source.width+x)*4+3]<12)continue;minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y)}if(maxX<minX)return source;const margin=3,w=maxX-minX+1+margin*2,h=maxY-minY+1+margin*2,out=makeCanvas(w,h);out.getContext('2d').drawImage(source,minX,minY,w-margin*2,h-margin*2,margin,margin,w-margin*2,h-margin*2);return out}
function rasterize(img){const scale=Math.min(1,1024/Math.max(img.width,img.height)),c=makeCanvas(Math.max(1,Math.round(img.width*scale)),Math.max(1,Math.round(img.height*scale)));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c}
const sampleCache=new Map();
async function setSample(type='blackwork'){const token=++generation;clearTimeout(processTimer);processingPending=false;selectedArt=type;rawUpload=null;rawPixels=null;uploadName='';simControls.upload.value='';simControls['upload-status'].textContent='Desenhos escuros sobre fundo claro funcionam melhor.';
 try{let ink=sampleCache.get('blackwork');if(!ink){const im=await loadImage(sampleSources.blackwork);ink=trimInk(rasterize(im));sampleCache.set('blackwork',ink)}if(token!==generation)return;commitInk(ink);$$('[data-art]').forEach(b=>b.classList.toggle('active',b.dataset.art==='blackwork'));$('.upload').classList.remove('active')}catch{if(token===generation)simControls['upload-status'].textContent='Não foi possível carregar esta arte.'}}
function processUpload(){clearTimeout(processTimer);processingPending=false;if(!rawUpload||!rawPixels)return;const out=makeCanvas(rawUpload.width,rawUpload.height),c=out.getContext('2d'),image=c.createImageData(out.width,out.height);image.data.set(rawPixels);const data=image.data,amount=+simControls.threshold.value,cutoff=255-amount*1.6;if(amount>0)for(let i=0;i<data.length;i+=4){const light=Math.min(data[i],data[i+1],data[i+2]);if(light>cutoff)data[i+3]*=clamp((255-light)/(255-cutoff));}c.putImageData(image,0,0);commitInk(trimInk(out))}
createPainter();
// Only one region resource is loaded/decoded/prepared at a time. A selection takes
// priority over queued warmup; identical requests share one promise.
const regionJobs=new Map(),regionQueue=[];
let regionWorker=false,warmStarted=false,warmNear=false,activeRegionJob=null,wakeRegionIdle=null;
const idleRegion=()=>new Promise(resolve=>{let id;const idle=typeof requestIdleCallback==='function',finish=()=>{if(wakeRegionIdle===wake)wakeRegionIdle=null;resolve()},wake=()=>{if(idle)cancelIdleCallback(id);else clearTimeout(id);finish()};wakeRegionIdle=wake;id=idle?requestIdleCallback(finish,{timeout:800}):setTimeout(finish,32)});
function loadRegionImage(src,background,job){return new Promise((resolve,reject)=>{const image=new Image();job.loadingImage=image;image.decoding='async';image.fetchPriority=background?'low':'auto';job.cancel=()=>{image.onload=image.onerror=null;try{image.src=''}catch{}job.cancel=null;reject(new Error('region-preempted'))};image.onload=()=>{job.cancel=null;Promise.resolve().then(()=>typeof image.decode==='function'?image.decode():undefined).then(()=>resolve(image),reject)};image.onerror=error=>{job.cancel=null;reject(error)};image.src=src})}
function prepareRegion(index,priority=true){if(painter.regionCache.has(index))return Promise.resolve(painter.regionCache.get(index).base);let job=regionJobs.get(index);if(job){job.priority=job.priority||priority;if(priority&&job.loadingImage)job.loadingImage.fetchPriority='high'}else{job={index,priority};job.promise=new Promise((resolve,reject)=>{job.resolve=resolve;job.reject=reject});regionJobs.set(index,job);regionQueue.push(job)}if(priority){if(wakeRegionIdle)wakeRegionIdle();if(activeRegionJob&&activeRegionJob!==job&&!activeRegionJob.priority&&activeRegionJob.cancel)activeRegionJob.cancel()}pumpRegions();return job.promise}
async function pumpRegions(){if(regionWorker)return;regionWorker=true;try{while(regionQueue.length){let at=regionQueue.findLastIndex(job=>job.priority);if(at<0)at=0;const job=regionQueue.splice(at,1)[0];activeRegionJob=job;try{if(!job.priority){await idleRegion();if(regionQueue.some(next=>next.priority)){regionQueue.unshift(job);continue}}const image=job.image||await loadRegionImage(NoirInk.REGIONS[job.index].src,!job.priority,job);if(!job.priority){await idleRegion();if(regionQueue.some(next=>next.priority)){job.image=image;regionQueue.unshift(job);continue}}const entry=painter.prepareBody(image,job.index);job.resolve(entry.base)}catch(error){if(error.message==='region-preempted')regionQueue.push(job);else job.reject(error)}finally{activeRegionJob=null;if(!regionQueue.includes(job)){regionJobs.delete(job.index);job.image=null;job.loadingImage=null}}}}finally{regionWorker=false}}
function startRegionWarmup(){if(warmStarted||!warmNear)return;if(!heroSettled||!body){setTimeout(startRegionWarmup,200);return}warmStarted=true;for(let i=1;i<NoirInk.REGIONS.length;i++)prepareRegion(i,false).catch(()=>{})}
if(typeof IntersectionObserver==='function'){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){warmNear=true;observer.disconnect();startRegionWarmup()}},{rootMargin:'1200px'});observer.observe($('.simulator'))}else{const near=()=>{if($('.simulator').getBoundingClientRect().top<innerHeight+1200){warmNear=true;startRegionWarmup();if(warmStarted)removeEventListener('scroll',near)}};addEventListener('scroll',near,{passive:true})}
async function selectRegion(index){const token=++regionRequest;regionLoading=true;regionReveal=true;drag=null;canvas.style.visibility='hidden';canvas.setAttribute('aria-busy','true');$('.canvas-tag').textContent='CARREGANDO REGIÃO…';try{const prepared=await prepareRegion(index);if(token!==regionRequest)return;body=prepared;painter.setBody(body,index);resetPosition()}catch{if(token!==regionRequest)return;simControls.region.selectedIndex=painter.region;simControls['upload-status'].textContent='Não foi possível carregar essa região. Tente novamente.'}finally{if(token===regionRequest){regionLoading=false;requestDraw()}}}
selectRegion(0);setSample('blackwork');
$$('[data-art]').forEach(b=>b.addEventListener('click',()=>setSample(b.dataset.art)));
['size','rotation','opacity'].forEach(id=>simControls[id].addEventListener('input',()=>{state[id]=+simControls[id].value;$('#'+id+'-value').textContent=state[id]+(id==='rotation'?'°':'%');requestDraw()}));
simControls.threshold.addEventListener('input',()=>{$('#threshold-value').textContent=simControls.threshold.value+'%';if(!rawUpload)return;clearTimeout(processTimer);processingPending=true;processTimer=setTimeout(processUpload,90)});
simControls.region.addEventListener('change',()=>selectRegion(simControls.region.selectedIndex));
canvas.addEventListener('pointerdown',e=>{if(regionLoading)return;const r=canvas.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,px:state.x,py:state.y,ratio:900/r.width};canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing'});
canvas.addEventListener('pointermove',e=>{if(!drag)return;state.x=drag.px+(e.clientX-drag.x)*drag.ratio;state.y=drag.py+(e.clientY-drag.y)*drag.ratio;constrainCenter();requestDraw()});
['pointerup','pointercancel','lostpointercapture'].forEach(event=>canvas.addEventListener(event,()=>{drag=null;canvas.style.cursor='grab'}));
canvas.addEventListener('keydown',e=>{if(regionLoading)return;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const step=e.shiftKey?12:4;state.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;state.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;constrainCenter();requestDraw()});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();simControls['upload-status'].textContent='Restaurando a prévia…'});
canvas.addEventListener('webglcontextrestored',()=>{const resources=painter.regionCache,restoredRegion=painter.region;painter=new NoirInk.SurfacePainter(canvas,makeCanvas);painter.regionCache=resources;if(body)painter.setBody(body,restoredRegion);if(tattoo)painter.setInk(tattoo);simControls['upload-status'].textContent=uploadName||'Prévia restaurada.';requestDraw()});
simControls.upload.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){simControls['upload-status'].textContent='Escolha PNG, JPG ou WEBP de até 10 MB.';e.target.value='';return}
 const token=++generation,url=URL.createObjectURL(file);simControls['upload-status'].textContent='Preparando sua referência…';loadImage(url).then(image=>{if(token!==generation)return;if(image.width*image.height>24000000){simControls['upload-status'].textContent='Use uma imagem de até 24 megapixels.';return}rawUpload=rasterize(image);rawPixels=rawUpload.getContext('2d',{willReadFrequently:true}).getImageData(0,0,rawUpload.width,rawUpload.height).data;uploadName=file.name;selectedArt='upload';$$('[data-art]').forEach(b=>b.classList.remove('active'));$('.upload').classList.add('active');resetPosition();processUpload();simControls['upload-status'].textContent=file.name+' · ajuste a remoção de fundo se necessário.'}).catch(()=>{if(token===generation)simControls['upload-status'].textContent='Não foi possível ler essa imagem. Tente outro arquivo.'}).finally(()=>URL.revokeObjectURL(url))});
$('#reset').onclick=()=>{resetPosition();for(const [id,value] of Object.entries({size:100,rotation:0,opacity:78,threshold:80})){simControls[id].value=value;$('#'+id+'-value').textContent=value+(id==='rotation'?'°':'%');if(id!=='threshold')state[id]=value}if(rawUpload)processUpload();else requestDraw()};
function flushPreview(){if(regionLoading||!body||!tattoo)return false;if(processingPending)processUpload();painter.draw(state);return true}
$('#download').onclick=()=>{if(!flushPreview())return;canvas.toBlob(b=>b&&download(b,'noir-estudo-tattoo.png'),'image/png')};$('#use-design').onclick=()=>{if(!flushPreview())return;capturedPreview=canvas.toDataURL('image/jpeg',.85);$('#form-region').value=$('#region').value;$('#attached').hidden=false;$('#attached').textContent='✓ Estudo de '+$('#region').value.toLowerCase()+' anexado ao briefing';$('#orcamento').scrollIntoView({behavior:reduced.matches?'instant':'smooth'})};
